-- =====================================================================
-- PROJETO DE BANCO DE DADOS 2026/2 - UFF - Prof. Marcos Bedo
-- Arquivo 1: DDL (tabelas em 3FN, constraints e índices de apoio)
--
-- Convenções:
--  * Identificadores artificiais: id_canal e id_video (GENERATED BY DEFAULT,
--    permitem carga com ids explícitos; ajustar as sequences após a carga).
--  * Doação: o usuário informa valor_original (na moeda do país de residência
--    de quem comentou). O trigger T16 converte para USD NO INSERT e grava
--    moeda e valor_usd (fator da época). Todo cálculo de receita usa valor_usd.
--    Patrocínio e níveis de membro já estão em USD.
--  * Colunas derivadas (plataforma.qtd_users, canal.qtd_videos,
--    canal.qtd_visualizacoes) são redundância controlada, mantidas pelos
--    triggers T1 e T2 (arquivo 2). Não são editadas pela aplicação.
--  * "Streamer" = usuário com ao menos um passaporte em streamer_pais.
--  * Colunas seq, seq_pg e seq_plataforma são preenchidas por triggers
--    (T7, T8, T8b) em BEFORE INSERT; por isso o INSERT pode omiti-las.
-- =====================================================================

DROP TABLE IF EXISTS mecanismo_plat    CASCADE;
DROP TABLE IF EXISTS cartao_credito    CASCADE;
DROP TABLE IF EXISTS paypal            CASCADE;
DROP TABLE IF EXISTS bitcoin           CASCADE;
DROP TABLE IF EXISTS doacao            CASCADE;
DROP TABLE IF EXISTS comentario        CASCADE;
DROP TABLE IF EXISTS participa         CASCADE;
DROP TABLE IF EXISTS video             CASCADE;
DROP TABLE IF EXISTS inscricao         CASCADE;
DROP TABLE IF EXISTS nivel_canal       CASCADE;
DROP TABLE IF EXISTS patrocinio        CASCADE;
DROP TABLE IF EXISTS canal             CASCADE;
DROP TABLE IF EXISTS streamer_pais     CASCADE;
DROP TABLE IF EXISTS plataforma_usuario CASCADE;
DROP TABLE IF EXISTS usuario           CASCADE;
DROP TABLE IF EXISTS plataforma        CASCADE;
DROP TABLE IF EXISTS empresa_pais      CASCADE;
DROP TABLE IF EXISTS pais              CASCADE;
DROP TABLE IF EXISTS conversao         CASCADE;
DROP TABLE IF EXISTS empresa           CASCADE;

CREATE TABLE conversao (
    moeda         varchar(3)    PRIMARY KEY,              
    nome          varchar(60)   NOT NULL,
    fator_conver  numeric(18,6) NOT NULL CHECK (fator_conver > 0)
);

CREATE TABLE pais (
    ddi    integer      PRIMARY KEY CHECK (ddi > 0),
    nome   varchar(80)  NOT NULL UNIQUE,
    moeda  varchar(3)   NOT NULL REFERENCES conversao(moeda)
);

CREATE TABLE empresa (
    id_empresa     integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome           varchar(120) NOT NULL,
    nome_fantasia  varchar(120)
);

CREATE TABLE empresa_pais (
    id_empresa   integer      NOT NULL REFERENCES empresa(id_empresa) ON DELETE CASCADE,
    ddi          integer      NOT NULL REFERENCES pais(ddi),
    id_nacional  varchar(30)  NOT NULL,
    PRIMARY KEY (id_empresa, ddi),
    UNIQUE (ddi, id_nacional)
);

CREATE TABLE plataforma (
    nro_plataforma  integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome            varchar(60) NOT NULL UNIQUE,
    empresa_fund    integer     NOT NULL REFERENCES empresa(id_empresa),
    empresa_respo   integer     NOT NULL REFERENCES empresa(id_empresa),
    data_fund       date        NOT NULL,
    qtd_users       integer     NOT NULL DEFAULT 0 CHECK (qtd_users >= 0)
);

CREATE TABLE usuario (
    nick             varchar(40)  PRIMARY KEY,
    email            varchar(120) NOT NULL UNIQUE,
    data_nasc        date         NOT NULL,
    telefone         varchar(25)  NOT NULL,          
    end_postal       varchar(200) NOT NULL,
    pais_residencia  integer      NOT NULL REFERENCES pais(ddi)
);

CREATE TABLE plataforma_usuario (
    nro_plataforma  integer     NOT NULL REFERENCES plataforma(nro_plataforma),
    nick_usuario    varchar(40) NOT NULL REFERENCES usuario(nick) ON DELETE CASCADE,
    nro_usuario     bigint      NOT NULL,
    PRIMARY KEY (nro_plataforma, nick_usuario),
    UNIQUE (nro_plataforma, nro_usuario)
);

CREATE TABLE streamer_pais (
    nick_streamer  varchar(40) NOT NULL REFERENCES usuario(nick) ON DELETE CASCADE,
    ddi_pais       integer     NOT NULL REFERENCES pais(ddi),
    nro_passaporte varchar(20) NOT NULL,
    PRIMARY KEY (nick_streamer, ddi_pais),
    UNIQUE (ddi_pais, nro_passaporte)
);

CREATE TABLE canal (
    id_canal           integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome               varchar(80)  NOT NULL,
    nro_plataforma     integer      NOT NULL REFERENCES plataforma(nro_plataforma),
    nick_streamer      varchar(40)  NOT NULL REFERENCES usuario(nick),     
    tipo               varchar(10)  NOT NULL CHECK (tipo IN ('privado','publico','misto')),
    data_inicio        date         NOT NULL,
    descricao          text,
    qtd_videos         integer      NOT NULL DEFAULT 0 CHECK (qtd_videos >= 0),         
    qtd_visualizacoes  bigint       NOT NULL DEFAULT 0 CHECK (qtd_visualizacoes >= 0),
    UNIQUE (nome, nro_plataforma)
);

CREATE TABLE patrocinio (
    id_empresa  integer       NOT NULL REFERENCES empresa(id_empresa),
    id_canal    integer       NOT NULL REFERENCES canal(id_canal) ON DELETE CASCADE,
    valor       numeric(12,2) NOT NULL CHECK (valor > 0),    
    PRIMARY KEY (id_empresa, id_canal)
);

CREATE TABLE nivel_canal (
    id_canal  integer       NOT NULL REFERENCES canal(id_canal) ON DELETE CASCADE,
    nivel     smallint      NOT NULL CHECK (nivel BETWEEN 1 AND 5),
    nome      varchar(40)   NOT NULL,
    valor     numeric(10,2) NOT NULL CHECK (valor > 0),      
    gif       varchar(255)  NOT NULL,                          
    PRIMARY KEY (id_canal, nivel),
    UNIQUE (id_canal, nome)
);

CREATE TABLE inscricao (
    nick_membro  varchar(40) NOT NULL REFERENCES usuario(nick) ON DELETE CASCADE,
    id_canal     integer     NOT NULL,
    nivel        smallint    NOT NULL,
    PRIMARY KEY (nick_membro, id_canal),
    FOREIGN KEY (id_canal, nivel) REFERENCES nivel_canal(id_canal, nivel)
);

CREATE TABLE video (
    id_video     integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_canal     integer      NOT NULL REFERENCES canal(id_canal),
    titulo       varchar(150) NOT NULL,
    data_hora    timestamp    NOT NULL,
    tema         varchar(60)  NOT NULL,
    duracao      interval     NOT NULL CHECK (duracao > interval '0'),
    visu_simul   integer      NOT NULL CHECK (visu_simul >= 0),
    visu_total   bigint       NOT NULL CHECK (visu_total >= 0),
    UNIQUE (id_canal, titulo, data_hora),
    CHECK (visu_simul <= visu_total)
);

-- streamers convidados (além do dono do canal)
CREATE TABLE participa (
    id_video       integer     NOT NULL REFERENCES video(id_video) ON DELETE CASCADE,
    nick_streamer  varchar(40) NOT NULL REFERENCES usuario(nick),
    PRIMARY KEY (id_video, nick_streamer)
);

CREATE TABLE comentario (
    id_video      integer      NOT NULL REFERENCES video(id_video) ON DELETE CASCADE,
    seq           integer      NOT NULL CHECK (seq > 0),            
    nick_usuario  varchar(40)  NOT NULL REFERENCES usuario(nick),
    texto         text         NOT NULL,
    data_hora     timestamp    NOT NULL,                            -- >= postagem do vídeo (T7)
    coment_on     boolean      NOT NULL,                            -- true = online, false = offline
    PRIMARY KEY (id_video, seq)
);

CREATE TABLE doacao (
    id_video          integer       NOT NULL,
    seq_comentario    integer       NOT NULL,
    seq_pg            integer       NOT NULL CHECK (seq_pg > 0),   
    valor_original    numeric(14,2) NOT NULL CHECK (valor_original > 0),  -- moeda do país do usuário
    moeda             varchar(3)    NOT NULL REFERENCES conversao(moeda), -- preenchida por T16
    valor_usd         numeric(16,4) NOT NULL CHECK (valor_usd > 0),         -- preenchido por T16
    status            varchar(10)   NOT NULL CHECK (status IN ('recusado','recebido','lido')),
    PRIMARY KEY (id_video, seq_comentario, seq_pg),
    FOREIGN KEY (id_video, seq_comentario) REFERENCES comentario(id_video, seq) ON DELETE CASCADE
);

CREATE TABLE bitcoin (
    id_video        integer      NOT NULL,
    seq_comentario  integer      NOT NULL,
    seq_pg          integer      NOT NULL,
    txid            varchar(100) NOT NULL UNIQUE,
    PRIMARY KEY (id_video, seq_comentario, seq_pg),
    FOREIGN KEY (id_video, seq_comentario, seq_pg)
        REFERENCES doacao(id_video, seq_comentario, seq_pg) ON DELETE CASCADE
);

CREATE TABLE paypal (
    id_video        integer      NOT NULL,
    seq_comentario  integer      NOT NULL,
    seq_pg          integer      NOT NULL,
    id_paypal       varchar(60)  NOT NULL UNIQUE,
    PRIMARY KEY (id_video, seq_comentario, seq_pg),
    FOREIGN KEY (id_video, seq_comentario, seq_pg)
        REFERENCES doacao(id_video, seq_comentario, seq_pg) ON DELETE CASCADE
);

CREATE TABLE cartao_credito (
    id_video        integer      NOT NULL,
    seq_comentario  integer      NOT NULL,
    seq_pg          integer      NOT NULL,
    nro_cartao      varchar(19)  NOT NULL,
    bandeira        varchar(30)  NOT NULL,
    data_hora       timestamp    NOT NULL,
    PRIMARY KEY (id_video, seq_comentario, seq_pg),
    FOREIGN KEY (id_video, seq_comentario, seq_pg)
        REFERENCES doacao(id_video, seq_comentario, seq_pg) ON DELETE CASCADE
);

CREATE TABLE mecanismo_plat (
    id_video         integer NOT NULL,
    seq_comentario   integer NOT NULL,
    seq_pg           integer NOT NULL,
    seq_plataforma   integer NOT NULL CHECK (seq_plataforma > 0),  
    PRIMARY KEY (id_video, seq_comentario, seq_pg),
    UNIQUE (id_video, seq_comentario, seq_plataforma),
    FOREIGN KEY (id_video, seq_comentario, seq_pg)
        REFERENCES doacao(id_video, seq_comentario, seq_pg) ON DELETE CASCADE
);

CREATE INDEX idx_canal_plataforma     ON canal (nro_plataforma);                    -- Q1, Q4, Q12
CREATE INDEX idx_patrocinio_canal     ON patrocinio (id_canal) INCLUDE (valor);     -- Q8, Q11
CREATE INDEX idx_inscricao_canal      ON inscricao (id_canal) INCLUDE (nivel);      -- Q9, Q11
CREATE INDEX idx_participa_streamer   ON participa (nick_streamer);                 -- T11, T14
